import type { Metadata } from 'next';
import socialImage from '@/assets/images/shared/fritz/social-share.jpg';
import { site } from './site';

const shareImage = {
  url: socialImage.src,
  width: socialImage.width,
  height: socialImage.height,
  alt: 'Fritz — Higienização e impermeabilização',
  type: 'image/jpeg',
};

export const siteMetadata: Metadata = {
  metadataBase: new URL(site.url),
  applicationName: site.name,
  title: { default: site.title, template: '%s | Fritz' },
  description: site.description,
  alternates: { canonical: '/' },
  category: 'Higienização e impermeabilização',
  robots: {
    index: site.indexable,
    follow: true,
    googleBot: {
      index: site.indexable,
      follow: true,
      'max-image-preview': 'large',
    },
  },
  openGraph: {
    title: site.title,
    description: site.description,
    url: '/',
    siteName: site.name,
    locale: 'pt_BR',
    type: 'website',
    images: [shareImage],
  },
  twitter: {
    card: 'summary_large_image',
    title: site.title,
    description: site.description,
    images: [shareImage],
  },
  verification: {
    google: process.env.GOOGLE_SITE_VERIFICATION || undefined,
    other: process.env.META_DOMAIN_VERIFICATION
      ? { 'facebook-domain-verification': process.env.META_DOMAIN_VERIFICATION }
      : undefined,
  },
};

export function pageMetadata(
  title: string,
  description: string,
  path: string,
  type: 'website' | 'article' = 'website',
): Metadata {
  return {
    title,
    description,
    alternates: { canonical: path },
    openGraph: {
      ...siteMetadata.openGraph,
      title,
      description,
      url: path,
      type,
    },
    twitter: { ...siteMetadata.twitter, title, description },
  };
}
